1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const COMPONENT_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_PREMIUM = 60;
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	
29	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
30	
31	const componentsBasePremium = (count: number): number =>
32	  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * COMPONENT_PREMIUM;
33	
34	const applyFirstInsuranceSurcharge = (amount: number): number =>
35	  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;
36	
37	const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);
38	
39	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
40	
41	const itemsBasePremium = (items: Item[]): number => {
42	  const components = items.filter(isComponent);
43	  const mainItems = items.filter((item) => !isComponent(item));
44	  const mainItemsTotal = mainItems.reduce((sum, item) => sum + basePremium(item), 0);
45	  return mainItemsTotal + componentsBasePremium(components.length);
46	};
47	
48	export const quote = (
49	  customer: Customer,
50	  items: Item[],
51	  contractIndex: number,
52	): number => {
53	  const base = itemsBasePremium(items);
54	  return roundInMhpcoFavor(applyFirstInsuranceSurcharge(base) + PROCESSING_FEE);
55	};
56	
57	export const claim = (): number => {
58	  return undefined as unknown as number;
59	};
