1	import { describe, it, expect } from "vitest";
2	import { quote, claim } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote", () => {
5	  // Edge case: empty list
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    expect(quote({ yearsWithMHPCO: 0 }, [], 0)).toBe(5);
8	  });
9	
10	  // Base premiums for single main items (base + 10% first insurance + 5 fee)
11	  it("single sword → base premium 100 G (total 100 + 10 first + 5 fee = 115)", () => {
12	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }], 0)).toBe(115);
13	  });
14	  it("single amulet → base premium 60 G (total 60 + 6 first + 5 fee = 71)", () => {
15	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }], 0)).toBe(71);
16	  });
17	  it("single staff → base premium 80 G (total 80 + 8 first + 5 fee = 93)", () => {
18	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }], 0)).toBe(93);
19	  });
20	  it("single potion → base premium 40 G (total 40 + 4 first + 5 fee = 49)", () => {
21	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }], 0)).toBe(49);
22	  });
23	
24	  // Components
25	  it("single rune → base premium 25 G (total 25 + 2.5 first + 5 fee = 32.5 → 33 rounded up)", () => {
26	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }], 0)).toBe(33);
27	  });
28	  it("single moonstone → base premium 25 G (total 32.5 → 33 rounded up)", () => {
29	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }], 0)).toBe(33);
30	  });
31	
32	  // Building block of 3 alike components
33	  it("2 runes → 50 G base premium (no block) (total 50 + 5 first + 5 fee = 60)", () => {
34	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }], 0)).toBe(60);
35	  });
36	  it("3 runes → 60 G base premium (block applies) (total 60 + 6 first + 5 fee = 71)", () => {
37	    expect(
38	      quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }, { type: "rune" }], 0),
39	    ).toBe(71);
40	  });
41	  it("4 runes → 100 G base premium (no block — requires exactly 3) (total 100 + 10 first + 5 fee = 115)", () => {
42	    expect(
43	      quote({ yearsWithMHPCO: 0 }, [
44	        { type: "rune" },
45	        { type: "rune" },
46	        { type: "rune" },
47	        { type: "rune" },
48	      ], 0),
49	    ).toBe(115);
50	  });
51	  it.todo("7 runes → 175 G base premium");
52	
53	  // "Alike" components — same type only
54	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
55	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
56	
57	  // Premium modifiers — item-specific
58	  it.todo("cursed sword adds 50% risk surcharge (50 G on base 100 G)");
59	  it.todo("highly enchanted sword (enchantment ≥ 5) adds 30% surcharge");
60	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
61	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
62	  it.todo("sword with enchantment 5 and cursed → both surcharges apply");
63	
64	  // Policy-wide modifiers
65	  it.todo("long-standing customer (≥ 2 years) receives 20% loyalty discount");
66	  it.todo("customer with exactly 2 years → loyalty discount applies");
67	  it.todo("first insurance carries 10% initial assessment surcharge");
68	  it.todo("15% discount on each contract after the first");
69	
70	  // Processing fee
71	  it.todo("a 5 G processing fee is added to every premium");
72	
73	  // Modifier scope on multi-item policies
74	  it.todo(
75	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (of cursed item base) → 210 G before further modifiers and fee",
76	  );
77	
78	  // Rounding in MHPCO's favor
79	  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
80	
81	  // Integration examples
82	  it.todo(
83	    "newcomer with cursed sword (steel, ench 3), 0 years → premium 165 G",
84	  );
85	  it.todo(
86	    "long-standing customer 2nd contract: cursed sword (steel, ench 7), 3 years → premium 160 G",
87	  );
88	  it.todo(
89	    "first insurance surcharge applies per item regardless of customer history",
90	  );
91	
92	  // Insurance sum / cap (exposed via quote result or claim)
93	  it.todo("two swords → insurance sum 2000 G, cap 4000 G");
94	  it.todo("sword + amulet → insurance sum 1600 G, cap 3200 G");
95	  it.todo("sword + 3 runes (block) → insurance sum 1750 G (block affects premium only)");
